I632098872a279ee4b6aa74fe6b017c9047d0e0b.patch_content:
commit a37ac9f0a9325cf4038db84796b74a2ee1c777f4
Author: dkkim <dkkim@humax-networks.com>
Date:   Mon Mar 2 13:39:45 2026 +0900

    [ARHT-197] [LEDCTRL] update operation mode initialization logic

     - Update the opermode setting logic in ledctrl_init()
     - For AP mode, add validation logic to check the 'ap:x:x:1' format
       from 'prolinecmd opermode' output
     - Fix an issue where LOS/PON LEDs do not operate correctly during
       transitions between AP and AUTO modes by ensuring proper
       initialization of the operation mode.

    Change-Id: I632098872a279ee4b6aa74fe6b017c9047d0e0b6

diff --git a/tclinux_phoenix/apps/hni/ledctrl/ledctrl.c b/tclinux_phoenix/apps/hni/ledctrl/ledctrl.c
index 7cebaefd3..abdfc7949 100755
--- a/tclinux_phoenix/apps/hni/ledctrl/ledctrl.c
+++ b/tclinux_phoenix/apps/hni/ledctrl/ledctrl.c
@@ -428,7 +428,6 @@ static void cleanup(int sig)
 static void ledctrl_init(void)
 {
     char buf[STR_LEN_128] = {0};
-    char def_setting[STR_LEN_8] = {0};

     // set to initial values
     g_opermode.mode = OPERMODE_AUTO;
@@ -449,8 +448,13 @@ static void ledctrl_init(void)
                 break;
             }
             else if (strstr(buf, "ap")) {
-                HalConfig_get("clay.opermode", "def_setting", def_setting, sizeof(def_setting));
-                if (atoi(def_setting) == 1) {
+                int value_tagged, value_vendorid, value_keep;
+                int ret = sscanf(buf, "Value=ap:%d:%d:%d", &value_tagged, &value_vendorid, &value_keep);
+                if (ret == 3 && value_keep == 1) { // Value=ap:0:1:1
+                    g_opermode.mode = OPERMODE_AP;
+                    g_opermode.uplink = UPLINK_LAN1;
+                }
+                else if (ret == 2) {
                     g_opermode.mode = OPERMODE_AUTO;
                     g_opermode.uplink = UPLINK_PON;
                 }

